class Solution {
    public long countPairs(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            boolean[] vis = new boolean[n];
            int reachable = dfs(i, adj, vis);
            total += (n - reachable);
        }
        return total / 2;
    }
    private int dfs(int u, List<List<Integer>> adj, boolean[] vis) {
        vis[u] = true;
        int cnt = 1;
        for (int v : adj.get(u)) {
            if (!vis[v]) cnt += dfs(v, adj, vis);
        }
        return cnt;
    }
}

