class Solution {
    public String smallestStringWithSwaps(String s, List<List<Integer>> pairs) {
        int n = s.length();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (List<Integer> p : pairs) {
            adj.get(p.get(0)).add(p.get(1));
            adj.get(p.get(1)).add(p.get(0));
        }
        boolean[] vis = new boolean[n];
        char[] ans = s.toCharArray();
        for (int i = 0; i < n; i++) {
            if (!vis[i]) {
                List<Integer> indices = new ArrayList<>();
                List<Character> chars = new ArrayList<>();
                dfs(i, adj, vis, indices, chars, s);
                Collections.sort(indices);
                Collections.sort(chars);
                for (int k = 0; k < indices.size(); k++) {
                    ans[indices.get(k)] = chars.get(k);
                }
            }
        }
        return new String(ans);
    }
    private void dfs(int u, List<List<Integer>> adj, boolean[] vis, List<Integer> idx, List<Character> ch, String s) {
        vis[u] = true;
        idx.add(u);
        ch.add(s.charAt(u));
        for (int v : adj.get(u)) {
            if (!vis[v]) dfs(v, adj, vis, idx, ch, s);
        }
    }
}

