class Solution {
    private int[] parent;
    private int count;
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        count = 4 * n * n;
        parent = new int[count];
        for (int i = 0; i < count; i++) parent[i] = i;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int base = 4 * (r * n + c);
                char ch = grid[r].charAt(c);
                if (ch == ' ') {
                    union(base, base + 1);
                    union(base + 1, base + 2);
                    union(base + 2, base + 3);
                } else if (ch == '/') {
                    union(base, base + 3);
                    union(base + 1, base + 2);
                } else {
                    union(base, base + 1);
                    union(base + 2, base + 3);
                }
                if (r + 1 < n) union(base + 2, 4 * ((r + 1) * n + c));
                if (c + 1 < n) union(base + 1, 4 * (r * n + c + 1) + 3);
            }
        }
        return count;
    }
    private int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    private void union(int i, int j) {
        int r1 = find(i), r2 = find(j);
        if (r1 != r2) { parent[r1] = r2; count--; }
    }
}

