class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int[][] g = new int[n * 3][n * 3];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                char ch = grid[r].charAt(c);
                if (ch == '/') {
                    g[r * 3][c * 3 + 2] = 1;
                    g[r * 3 + 1][c * 3 + 1] = 1;
                    g[r * 3 + 2][c * 3] = 1;
                } else if (ch == '\\') {
                    g[r * 3][c * 3] = 1;
                    g[r * 3 + 1][c * 3 + 1] = 1;
                    g[r * 3 + 2][c * 3 + 2] = 1;
                }
            }
        }
        int regions = 0;
        for (int i = 0; i < n * 3; i++) {
            for (int j = 0; j < n * 3; j++) {
                if (g[i][j] == 0) {
                    regions++;
                    dfs(g, i, j);
                }
            }
        }
        return regions;
    }
    private void dfs(int[][] g, int r, int c) {
        if (r < 0 || r >= g.length || c < 0 || c >= g[0].length || g[r][c] != 0) return;
        g[r][c] = 1;
        dfs(g, r + 1, c);
        dfs(g, r - 1, c);
        dfs(g, r, c + 1);
        dfs(g, r, c - 1);
    }
}

