        n = len(grid)
        g = [[0] * (n * 3) for _ in range(n * 3)]
        for r in range(n):
            for c in range(n):
                if grid[r][c] == '/':
                    g[r * 3][c * 3 + 2] = 1
                    g[r * 3 + 1][c * 3 + 1] = 1
                    g[r * 3 + 2][c * 3] = 1
                elif grid[r][c] == '\\':
                    g[r * 3][c * 3] = 1
                    g[r * 3 + 1][c * 3 + 1] = 1
                    g[r * 3 + 2][c * 3 + 2] = 1
        def dfs(r: int, c: int) -> None:
            if not (0 <= r < n * 3 and 0 <= c < n * 3 and g[r][c] == 0):
                return
            g[r][c] = 1
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)
        regions = 0
        for i in range(n * 3):
            for j in range(n * 3):
                if g[i][j] == 0:
                    regions += 1
                    dfs(i, j)
        return regions

