    public int[] loudAndRich(int[][] richer, int[] quiet) {
        int n = quiet.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] r : richer) adj.get(r[1]).add(r[0]);
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            boolean[] vis = new boolean[n];
            ans[i] = dfs(i, adj, quiet, vis);
        }
        return ans;
    }
    private int dfs(int u, List<List<Integer>> adj, int[] quiet, boolean[] vis) {
        vis[u] = true;
        int best = u;
        for (int v : adj.get(u)) {
            if (!vis[v]) {
                int cand = dfs(v, adj, quiet, vis);
                if (quiet[cand] < quiet[best]) best = cand;
            }
        }
        return best;
    }
}

