class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        for (int i = n - 1; i >= 0; i--) {
            if (isValidTree(edges, i, n)) return edges[i];
        }
        return new int[0];
    }
    private boolean isValidTree(int[][] edges, int skip, int n) {
        int[] parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;
        int[] inDegree = new int[n + 1];
        for (int i = 0; i < edges.length; i++) {
            if (i == skip) continue;
            int u = edges[i][0], v = edges[i][1];
            inDegree[v]++;
            if (inDegree[v] > 1) return false;
            int r1 = find(parent, u), r2 = find(parent, v);
            if (r1 == r2) return false;
            parent[r1] = r2;
        }
        return true;
    }
    private int find(int[] p, int i) {
        if (p[i] == i) return i;
        return p[i] = find(p, p[i]);
    }
}

